#[derive(Debug, Clone)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    let epsilon = 2; // Fixed machine epsilon
    let threshold = tol * epsilon;

    // Check if all imaginary parts are close to zero
    let all_close_to_zero = arr.iter().all(|c| c.imag.abs() <= threshold);

    if all_close_to_zero {
        // Create a new vector with imaginary parts set to zero
        arr.iter()
            .map(|c| Complex { real: c.real, imag: 0 })
            .collect()
    } else {
        // Return the input array unchanged
        arr
    }
}

fn main() {
    // Example usage
    let complex_numbers = vec![
        Complex { real: 1, imag: 0 },
        Complex { real: 2, imag: 1 },
        Complex { real: 3, imag: 0 },
    ];
    let tolerance = 1;

    let result = real_if_close(complex_numbers, tolerance);
    for c in result {
        println!("Complex: real = {}, imag = {}", c.real, c.imag);
    }
}